frappe.ui.form.on("Shop CT", {
  dl_button: function(frm, cdt, cdn) {
    var currentRow = locals[cdt][cdn];
    var table = frm.fields_dict.table_2.grid; // Replace "table_2" with the actual child table fieldname
    
    
    // Get the index of the current row
    var currentIndex = null;
    for (var i = 0; i < table.grid_rows.length; i++) {
      if (table.grid_rows[i].doc === currentRow) {
        currentIndex = i;
        break;
      }
    }
    
    // Check the above row's di_created field value
    if (currentIndex > 0) {
      var aboveRow = table.grid_rows[currentIndex - 1];
      var aboveRowData = aboveRow.doc;
      
      if (aboveRowData.di_created === 0 && aboveRowData.skip === 0) {
        frappe.msgprint("Cannot perform the action in the current row.");
        return;
      }

    }
     set_r(frm, cdt, cdn);
    
  }
});

