    },
    item_code(frm, cdt, cdn) {
        set_cal(frm, cdt, cdn);
    }
});

function set_cal(frm, cdt, cdn) {
    let d = locals[cdt][cdn];
    if (!d.qty) return;

    let res = d.qty / 2;
    let rese = d.qty;

    if (frm.doc.stock_entry_type === "Material Unloading" || frm.doc.stock_entry_type === "Material Loading" || frm.doc.stock_entry_type === "Material Transfer") {
        frappe.model.set_value(d.doctype, d.name, 'total_number_of_bags', rese);

        if (["C05", "F05", "FL05", "F-05","FL-05","C-05"].includes(d.item_code)) {
            frappe.model.set_value(d.doctype, d.name, 'bags_in_10kgs', res);
            console.log('working')
        } else {
            frappe.model.set_value(d.doctype, d.name, 'bags_in_10kgs', rese);
        }
    } else {
        frappe.model.set_value(d.doctype, d.name, 'total_number_of_bags', rese);
        frappe.model.set_value(d.doctype, d.name, 'bags_in_10kgs', rese);
    }
}

