function update_total_bags(frm) {
    let total_present = 0;
    frm.doc.items.forEach(function(row) {
        total_present += Number(row.bags_in_10kgs) || 0;
    });
    frm.set_value('no_of_bags', total_present);
    frm.refresh_field('no_of_bags');
}



