	validate: function(frm) {
		TotalDiscount(frm);
		GrossTotal(frm);
	}
});


function TotalDiscount(frm) {
	const ct = frm.doc.items || [];
	let totaldiscount = 0;

	ct.forEach(row => {
		if (row.discount_amount) {
			totaldiscount += parseFloat(row.discount_amount);
		}
	});

	frm.set_value('total_discount', parseFloat(totaldiscount.toFixed(3)));
}


function GrossTotal(frm) {
	const ct = frm.doc.items || [];
	let grosstotal = 0;

	ct.forEach(row => {
		if (row.price_list_rate && row.qty) {
			grosstotal += parseFloat(row.gross_rate);
		}
	});

	frm.set_value('gross_total', parseFloat(grosstotal.toFixed(3)));
}

