frappe.listview_settings["Distributor Invoice"] = {
    onload: function (listview) {
        listview.page.add_inner_button(
            __("Create Invoices"),
            function () {
                open_create_invoice_dialog();
            }
        );
    }
};

function open_create_invoice_dialog() {
    let dialog = new frappe.ui.Dialog({
        title: __("Create Invoices"),
        fields: [
            {
                label: __("Invoice Date"),
                fieldname: "invoice_date",
                fieldtype: "Date",
                reqd: 1
            }
        ],
        primary_action_label: __("Create"),
        primary_action(values) {
            frappe.call({
                method: "create_di_on_button_click",
                args: {
                    target_date: values.invoice_date
                },
                freeze: true,
                freeze_message: __("Creating invoices..."),
                callback: function (r) {
                    if (!r.exc) {
                        frappe.msgprint({
                            title: __("Success"),
                            message: __("Invoices created successfully"),
                            indicator: "green"
                        });
                        dialog.hide();
                        cur_list.refresh();
                    }
                }
            });
        }
    });

    dialog.show();
}
